def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)

            if bottom - top < 2 or right - left < 2:
                continue

            perimeter = {
                (y, x)
                for y in range(top, bottom + 1)
                for x in range(left, right + 1)
                if y in (top, bottom) or x in (left, right)
            }
            if not perimeter.issubset(set(cells)):
                continue

            fill = 7 if bottom - top == 2 and right - left == 2 else 2
            for y in range(top + 1, bottom):
                for x in range(left + 1, right):
                    if grid[y][x] == 6:
                        out[y][x] = fill

    return out
